compile.workshop:
variables {
    global:
        0: value
}

rule ("issue 47 switch structured target") {
    event {
        Ongoing - Global;
    }
    actions {
        If(True);
            Skip(Value In Array(Array(7, 0, 6), Add(1, Index Of Array Value(Array(1, 2), Global.value))));
        //__label_switch_2_0__:
        If(Compare(Global.value, ==, 1));
            Set Global Variable(value, 2);
        End;
        While(Compare(Global.value, <, 0));
            Modify Global Variable(value, Add, 1);
        End;
        //__label_switch_2_1__:
        Set Global Variable(value, 3);
        //__label_switch_2_default__:
        Set Global Variable(value, 4);
        End;
    }
}

